@startuml

class City {
  + name : string
}

class H2SLocation {
  + address : string
}

class Resident {
  + name : string
  + streetAddress : string
  + phoneNumber : string
  + email : string
}

class PickupRequest {
  + requestedDate : date
  + pickupTimeWindow : string
  + itemDescription : string
}

class Item {
  + description : string
  + weight : float
  + dimensions : string
  + category : string
  + rfidTag : string
}

class Vehicle {
  + vehicleNumber : string
  + storageCapacity : float
}

class VolunteerDriver {
  + name : string
  + availableDays : string[]
}

class Route {
  + date : date
}

class DistributionCenter {
  + address : string
}

class FoodBank {
  + address : string
}

class Employee {
  + name : string
}

class Client {
  + name : string
  + homeAddress : string
  + neededCategories : string[]
}

class Category {
  + categoryName : string
}

City "1" *-- "1..*" H2SLocation
H2SLocation "1" *-- "1" DistributionCenter
H2SLocation "1" *-- "0..1" FoodBank

Resident "1" -- "0..*" PickupRequest
PickupRequest "1" *-- "1..*" Item

Vehicle "1" -- "1..*" Route
VolunteerDriver "1" -- "1..*" Route
Route "1" *-- "1..*" PickupRequest

Item "1" -- "1" Category
Employee "1" -- "1..*" Item : examines

Client "1" -- "1..*" Employee : contactedBy
Client "1" -- "0..*" Item : requests
Employee "1" -- "0..*" Client : arrangesDelivery

DistributionCenter "1" *-- "1..*" Item : stores
DistributionCenter "1" -- "1..*" Vehicle : operates
DistributionCenter "1" -- "1..*" Employee : employs

@enduml

